@startuml

class User {
  + ID : int
  + name : string
  + email : string
  + dateOfBirth : date
}

class Account {
  + accountNumber : int
}

class PersonalAccount extends Account {}

class BusinessAccount extends Account {
  + companyName : string
  + monthlyFee : float
}

class Page {
  + name : string
  + numberOfVisits : int
}

class AdvertisementPage extends Page {
  + bounceRate : float
  + clickThroughRate : float
  + conversionRate : float
}

User "1" -- "1" Account
BusinessAccount "1" -- "*" Page
PersonalAccount "1" -- "*" Page
PersonalAccount "1" -- "*" PersonalAccount : friendRequest

@enduml

